pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address _owner) public {
        vm.assume(caller != address(0));
        // Admin is the deployer of setUp, which is this contract.
        // For admin to call setOwner, caller must be address(this).
        // We restrict to only the admin because the bug manifests only when the admin
        // calls setOwner and the resulting owner differs from the passed argument.
        // The fuzzer explores all possible _owner values. The rule: after an admin calls
        // setOwner with _owner, the contract's owner must equal the supplied _owner.
        vm.assume(caller == address(this));
        vm.prank(caller);
        c.setOwner(_owner);
        assertEq(c.owner(), _owner);
    }
}

