pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address initialOwner = c.owner();
        address newOwner = address(uint160(uint256(keccak256(abi.encodePacked(caller, "new")))));
        vm.assume(newOwner != initialOwner);
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool) {} catch {}
        address finalOwner = c.owner();
        if (caller == address(uint160(uint256(keccak256(abi.encodePacked("admin")))))) {
            // The admin is the deployer of C in setUp (this contract).
            // Since the deployer is not fuzzable, the only way to be admin is to be the deployer.
            // The fuzzer cannot be the admin because the admin is set during setUp.
            // We don't need to handle this case because the fuzzer cannot be admin.
        }
        assertTrue(finalOwner == initialOwner);
    }
}

