        // First, admin sets owner to some value
        address adminOwner = address(uint160(0x1234));
        c.setOwner(adminOwner);

        // Capture admin's view of what setOwner(newOwner) would produce
        address expectedOwner = newOwner;

        // Now have nonAdmin call setOwner with the same newOwner
        vm.prank(nonAdmin);
        c.setOwner(newOwner);

        // The owner after nonAdmin's call should still equal the admin's expected result
        // (since admin is the only authorized caller in reference; bug allows nonAdmin)
        assertTrue(c.owner() == expectedOwner);
    }
}

