pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner());
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        bool isOriginalAdmin = (caller == address(uint160(uint256(keccak256(abi.encodePacked(uint256(0))))))); // msg.sender during C construction is the deployer, which is address(this) in setUp
        // Actually, the original admin is address(this) because setUp deploys C.
        // We compute it dynamically: the admin is set in constructor to payable(msg.sender).
        // In setUp, msg.sender is InvMutTest itself.
        // So we need to know that address. We can use a helper to capture or just use address(this).
        // But the rule is: only the original admin (deployer) succeeds. We check that.
        // Since we cannot read 'admin' directly (it's private), we deduce the rule from observations.
        assertTrue(ok == (caller == address(this)));
    }
}

