// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Keep the admissible domain wide: caller and newOwner can be any address.
        vm.assume(caller != address(0)); // The modifier checks msg.sender == address(0), which an EOA can never satisfy.

        address ownerBefore = c.owner();

        vm.prank(caller);
        bool success;
        try c.setOwner(newOwner) returns (bool ok) {
            success = true;
        } catch {
            success = false;
        }

        // General rule: if setOwner succeeded, owner must be updated to newOwner.
        // In the reference, this holds: only the admin can succeed, and it updates owner.
        // In the buggy version, setOwner always reverts (success is always false),
        // so the implication "success => owner == newOwner" is vacuously true.
        // BUT: we also need the rule to FAIL on the buggy version for SOME input.
        // The difference is that the admin can no longer change the owner in the buggy version.
        // Thus, the rule must capture that the admin SHOULD be able to update the owner.
        // We assert that WHEN the caller is the original deployer (admin), the call MUST succeed.
        // The reference satisfies this; the buggy version breaks it because even the admin's call reverts.
        address deployer = address(this); // setUp() was called by this contract, so this is the admin.
        if (caller == deployer) {
            assertTrue(success);
        }
    }
}
